import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';

function expandInstancedMeshes(root) {
  const toRemove = [];
  const toAdd = [];

  root.updateMatrixWorld(true);

  root.traverse((child) => {
    if (!child.isInstancedMesh) return;

    const parent = child.parent;
    if (!parent) return;

    child.updateMatrixWorld(true);
    child.updateMatrix();

    const instanceMatrix = new THREE.Matrix4();
    const localMatrix = new THREE.Matrix4();

    for (let i = 0; i < child.count; i++) {
      child.getMatrixAt(i, instanceMatrix);

      // Local transform relative to parent: instanced local * instance local
      localMatrix.multiplyMatrices(child.matrix, instanceMatrix);

      const mesh = new THREE.Mesh(child.geometry, child.material);
      mesh.name = `${child.name || 'instance'}_${i}`;
      mesh.matrixAutoUpdate = false;
      mesh.matrix.copy(localMatrix);

      toAdd.push({ parent, mesh });
    }

    toRemove.push(child);
  });

  for (const { parent, mesh } of toAdd) {
    parent.add(mesh);
  }

  for (const instanced of toRemove) {
    instanced.parent?.remove(instanced);
  }

  root.updateMatrixWorld(true);
}

function exportObj() {
  const root = createScene();

  // Expand instances so OBJ export preserves per-instance transforms.
  expandInstancedMeshes(root);

  // Convert Y-up to Z-up for Blender by rotating -90 degrees around X.
  const wrapper = new THREE.Group();
  wrapper.name = 'z_up_wrapper';
  wrapper.rotation.x = -Math.PI / 2;
  wrapper.add(root);

